INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "昭宗大赦改元龙纪", "start_year": 889, "end_year": 889, "time_original": "889年正月癸巳朔", "dynasty": "唐", "description": "昭宗在正月朔日赦天下，改元龙纪。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "4a6d8b17-4011-56fe-a8a5-795f591449bb"}, {"title": "刘崇望拜相", "start_year": 889, "end_year": 889, "time_original": "889年正月；具体日未载", "dynasty": "唐", "description": "朝廷以翰林学士承旨、兵部侍郎刘崇望同平章事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "722ae9e6-5a70-576d-aba0-f50cee7ac493"}, {"title": "庞师古拔宿迁并驻吕梁", "start_year": 889, "end_year": 889, "time_original": "889年正月；具体日未载", "dynasty": "唐", "description": "汴将庞师古攻取宿迁，驻军吕梁。", "phases": [], "location_name": "宿迁、吕梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6bd6178c-cb17-5e28-bd58-cc2d2a0ba29c"}, {"title": "时溥迎战庞师古败退彭城", "start_year": 889, "end_year": 889, "time_original": "889年正月；具体日未载", "dynasty": "唐", "description": "时溥迎战庞师古，大败后退守彭城。", "phases": [], "location_name": "吕梁、彭城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "de51ca6e-4634-5f6b-851e-d4c4e6c36fb7"}, {"title": "郭璠杀申丛送秦宗权至汴", "start_year": 889, "end_year": 889, "time_original": "889年正月壬子", "dynasty": "唐", "description": "蔡将郭璠杀申丛，将秦宗权送到汴，向朱全忠声称申丛谋再立秦宗权。", "phases": [], "location_name": "汴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ad5e23c4-005b-54f2-809a-844ff5637527"}, {"title": "朱全忠以郭璠为淮西留后", "start_year": 889, "end_year": 889, "time_original": "889年正月壬子条", "dynasty": "唐", "description": "朱全忠以郭璠为淮西留后。", "phases": [], "location_name": "淮西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d25f9522-e5a3-5ed2-9a64-b194df484d84"}, {"title": "王建败山行章于新繁", "start_year": 889, "end_year": 889, "time_original": "889年正月条；原文戊申", "dynasty": "唐", "description": "王建在新繁大败山行章，《通鉴》记杀获近万人，山行章仅以身免。", "phases": [], "location_name": "新繁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e2693ece-edb1-5497-9fb1-caf39fc1d6f9"}, {"title": "杨晟山行章转屯与王建相持", "start_year": 889, "end_year": 889, "time_original": "889年正月条；新繁戊申战后", "dynasty": "唐", "description": "杨晟惧而移屯三交，山行章屯濛阳，与王建相持。", "phases": [], "location_name": "三交、濛阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7be74d39-d1b3-5cf7-abf7-294fa914b41c"}, {"title": "秦宗权送京师处斩", "start_year": 889, "end_year": 889, "time_original": "889年二月；具体日未载", "dynasty": "唐", "description": "朱全忠将秦宗权送到京师，秦宗权被斩于独柳，京兆尹孙揆监刑。秦宗权在槛车中自辩只是输忠不效，观者皆笑。", "phases": [], "location_name": "京师、独柳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "618e184c-7be6-5b53-9466-265e750f9189"}, {"title": "朱全忠加中书令进爵东平郡王", "start_year": 889, "end_year": 889, "time_original": "889年三月；具体日未载", "dynasty": "唐", "description": "朝廷加朱全忠兼中书令，进爵东平郡王；《通鉴》述其克蔡州后军势益盛。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "61cebe17-6cbc-5bdb-a6d7-d62ef8a35405"}, {"title": "赵德諲赵犨加官及忠武移治陈州", "start_year": 889, "end_year": 889, "time_original": "889年三月；具体日未载", "dynasty": "唐", "description": "朝廷加奉国节度使赵德諲中书令，加蔡州节度使赵犨同平章事并充忠武节度使，以陈州为治所。", "phases": [], "location_name": "陈州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6fb9a083-998a-5b0e-99f4-ca6f77e6370d"}, {"title": "赵犨病请退，赵昶继领忠武", "start_year": 889, "end_year": 889, "time_original": "889年三月条；具体日未载", "dynasty": "唐", "description": "赵犨患病，将军府事务交给弟赵昶，上表请求退休，朝廷诏以赵昶代为忠武节度使。", "phases": [], "location_name": "陈州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "491d50b3-65d1-5156-aab7-5ee05d7426e3"}, {"title": "赵犨退任后去世", "start_year": 889, "end_year": 889, "time_original": "889年三月条后未几；具体日未载", "dynasty": "唐", "description": "赵犨退任后不久去世。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f4e47b7f-b961-575c-8987-41aa57c02076"}, {"title": "钱銶拔苏州，徐约逃海死亡", "start_year": 889, "end_year": 889, "time_original": "889年三月丙申", "dynasty": "唐", "description": "钱銶攻取苏州，徐约逃入海中而死。", "phases": [], "location_name": "苏州、海上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "da1a2dee-c1b8-549d-9b1e-781c9b0d1049"}, {"title": "钱镠以沈粲权知苏州", "start_year": 889, "end_year": 889, "time_original": "889年三月丙申条；苏州攻取后", "dynasty": "唐", "description": "钱镠以海昌都将沈粲权知苏州。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e10f63fc-435a-5933-bb81-8b231506f71c"}, {"title": "陕虢军获赐保义军号", "start_year": 889, "end_year": 889, "time_original": "889年四月", "dynasty": "唐", "description": "朝廷赐陕虢军号保义。", "phases": [], "location_name": "陕虢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "133d8357-981a-5b75-b2c4-65897afbc0e4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

